"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([["85245"],{75243(e,t,n){n.r(t),n.d(t,{metadata:()=>a,default:()=>u,frontMatter:()=>s,contentTitle:()=>o,toc:()=>c,assets:()=>l});var a=JSON.parse('{"id":"tianya/garbageculture","title":"","description":"Culture -- \\"wen\\" means pattern; \\"hua\\" means the positive and negative of the human form. Culture, in essence, is the trace of the human\'s positive and negative, good and evil, in presence -- or the presence of traces. Entertainment is of course not simply compounded happiness. Against the backdrop of capital globalization, entertainment is a postmodern sacrificial ritual: the masses are the sacrifice, capital is God, that\'s all. Just as all sacrificial rites are based on the ignorance of the masses, postmodern sacrifice won\'t become post-sacrificial just because it\'s postmodern -- it only becomes more repressive for being hidden.","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/tianya/garbageculture.md","sourceDirName":"tianya","slug":"/tianya/garbageculture","permalink":"/en/tianya/garbageculture","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"garbageculture","title":"","hide_table_of_contents":true,"sidebar_label":"Entertainment is fool-tainment; the prevalence of garbage like Super Girl marks the complete trashification of culture"},"sidebar":"tianyaSidebar","previous":{"title":"Serious discussion: in an era of open thought, do we have the necessity and obligation to study the Lin Biao question?","permalink":"/en/tianya/linbiaoproblem"},"next":{"title":"Five regulated verses on Taiwan and related issues","permalink":"/en/tianya/5taiwanpoems"}}'),i=n(74848),r=n(28453);let s={id:"garbageculture",title:"",hide_table_of_contents:!0,sidebar_label:"Entertainment is fool-tainment; the prevalence of garbage like Super Girl marks the complete trashification of culture"},o="Entertainment Is Fool-tainment -- The Prevalence of Garbage Like Super Girl Marks the Complete Garbagification of Culture.",l={},c=[];function h(e){let t={h1:"h1",header:"header",p:"p",...(0,r.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(t.header,{children:(0,i.jsx)(t.h1,{id:"entertainment-is-fool-tainment----the-prevalence-of-garbage-like-super-girl-marks-the-complete-garbagification-of-culture",children:"Entertainment Is Fool-tainment -- The Prevalence of Garbage Like Super Girl Marks the Complete Garbagification of Culture."})}),"\n",(0,i.jsx)(t.p,{children:"Culture -- \"wen\" means pattern; \"hua\" means the positive and negative of the human form. Culture, in essence, is the trace of the human's positive and negative, good and evil, in presence -- or the presence of traces. Entertainment is of course not simply compounded happiness. Against the backdrop of capital globalization, entertainment is a postmodern sacrificial ritual: the masses are the sacrifice, capital is God, that's all. Just as all sacrificial rites are based on the ignorance of the masses, postmodern sacrifice won't become post-sacrificial just because it's postmodern -- it only becomes more repressive for being hidden."}),"\n",(0,i.jsx)(t.p,{children:"Entertainment is fool-tainment. The prevalence of garbage like Super Girl marks the complete garbagification of culture. More importantly, when the masses participate in postmodern sacrificial rituals through being entertained, all the dirty business of human-blood steamed buns continues being done. The foolishly grinning masses have their own blood dripping from the corners of their mouths. The vital essence of the masses' thought drains away in entertainment. Pallor is the base color of all sacrifice -- like zombies, the zombie of entertainment was already dead before it began."}),"\n",(0,i.jsx)(t.p,{children:"Thought is heavy. Being unable to bear thought can only demonstrate the bearer's weakness. A nation that cannot bear thought is a powerless nation. The postmodern of deconstruction has deconstructed thought, but it will never deconstruct bearing. Bearing is forever present. Bearing is the human being itself."}),"\n",(0,i.jsx)(t.p,{children:"Those who attempt to flee from bearing are shameful, regardless of whether that attempt is named entertainment. One who flees from bearing is one who flees from being human. One who has fled from being human can only be a non-human human."}),"\n",(0,i.jsx)(t.p,{children:"In the sacrificial rite of entertainment, everything is numbed entertainingly. Numbness sometimes is not numb, and that not-numb numbness portends an even greater numbness -- for example, climax is the greatest numbness."}),"\n",(0,i.jsx)(t.p,{children:"Yet the greatness of life lies in this: amid the numbness, life still lives. The altar will ultimately fall, but the tree of life is evergreen."})]})}function u(e={}){let{wrapper:t}={...(0,r.R)(),...e.components};return t?(0,i.jsx)(t,{...e,children:(0,i.jsx)(h,{...e})}):h(e)}},28453(e,t,n){n.d(t,{R:()=>s,x:()=>o});var a=n(96540);let i={},r=a.createContext(i);function s(e){let t=a.useContext(r);return a.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function o(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:s(e.components),a.createElement(r.Provider,{value:t},e.children)}}}]);